-- Cleaned schema for gaming_etc
-- From: supabase_me.stoikal pg_dump
-- Stripped: auth, extensions, graphql, pgbouncer, realtime, storage, vault
-- Stripped: public (motifs), reading_gaming, weekly
-- Stripped: ROLES, GRANTS, POLICIES, RLS, auth FKs, auth.uid() defaults

CREATE SCHEMA IF NOT EXISTS gaming;

-- Name: games_comments; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.games_comments (
    comment text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    game_id integer NOT NULL,
    user_id uuid NOT NULL
);


ALTER TABLE gaming.games_comments OWNER TO postgres;

--
-- Name: games_statuses; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.games_statuses (
    user_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    game_id integer NOT NULL,
    status text NOT NULL DEFAULT 'todo'::text,
    CONSTRAINT games_statuses_status_check CHECK ((status = ANY (ARRAY['todo'::text, 'playing'::text, 'finished'::text])))
);


ALTER TABLE gaming.games_statuses OWNER TO postgres;

--
-- Name: games; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.games (
    id integer NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text,
    first_release_date bigint
);


ALTER TABLE gaming.games OWNER TO postgres;

--
-- Name: games_genres; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.games_genres (
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    game_id integer NOT NULL,
    genre_id smallint NOT NULL
);


ALTER TABLE gaming.games_genres OWNER TO postgres;

--
-- Name: games_id_seq; Type: SEQUENCE; Schema: gaming; Owner: postgres
--

ALTER TABLE gaming.games ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME gaming.games_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: games_platforms; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.games_platforms (
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    game_id integer NOT NULL,
    platform_id smallint NOT NULL
);


ALTER TABLE gaming.games_platforms OWNER TO postgres;

--
-- Name: genres; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.genres (
    id smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text,
    slug text,
    url text
);


ALTER TABLE gaming.genres OWNER TO postgres;

--
-- Name: genres_id_seq; Type: SEQUENCE; Schema: gaming; Owner: postgres
--

ALTER TABLE gaming.genres ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME gaming.genres_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: list_items; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.list_items (
    list_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    game_id integer NOT NULL
);


ALTER TABLE gaming.list_items OWNER TO postgres;

--
-- Name: lists; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.lists (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    title text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE gaming.lists OWNER TO postgres;

--
-- Name: platform_categories; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.platform_categories (
    id smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text
);


ALTER TABLE gaming.platform_categories OWNER TO postgres;

--
-- Name: platform_categories_id_seq; Type: SEQUENCE; Schema: gaming; Owner: postgres
--

ALTER TABLE gaming.platform_categories ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME gaming.platform_categories_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: platforms; Type: TABLE; Schema: gaming; Owner: postgres
--

CREATE TABLE gaming.platforms (
    id smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    name text,
    slug text,
    category smallint,
    logo_url text,
    url text,
    alternative_name text,
    logo_id smallint
);


ALTER TABLE gaming.platforms OWNER TO postgres;

--
-- Name: platforms_id_seq; Type: SEQUENCE; Schema: gaming; Owner: postgres
--

ALTER TABLE gaming.platforms ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME gaming.platforms_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);



-- PRIMARY KEY CONSTRAINTS

ALTER TABLE ONLY gaming.games_comments
    ADD CONSTRAINT games_comments_pkey PRIMARY KEY (game_id, user_id);


ALTER TABLE ONLY gaming.games_statuses
    ADD CONSTRAINT games_statuses_pkey PRIMARY KEY (user_id, game_id);


ALTER TABLE ONLY gaming.games_genres
    ADD CONSTRAINT games_genres_pkey PRIMARY KEY (game_id, genre_id);


ALTER TABLE ONLY gaming.games
    ADD CONSTRAINT games_pkey PRIMARY KEY (id);


ALTER TABLE ONLY gaming.games_platforms
    ADD CONSTRAINT games_platforms_pkey PRIMARY KEY (game_id, platform_id);


ALTER TABLE ONLY gaming.genres
    ADD CONSTRAINT genres_pkey PRIMARY KEY (id);


ALTER TABLE ONLY gaming.list_items
    ADD CONSTRAINT list_items_pkey PRIMARY KEY (list_id, game_id);

ALTER TABLE ONLY gaming.lists
    ADD CONSTRAINT lists_pkey PRIMARY KEY (id);


ALTER TABLE ONLY gaming.platform_categories
    ADD CONSTRAINT platform_categories_pkey PRIMARY KEY (id);


ALTER TABLE ONLY gaming.platforms
    ADD CONSTRAINT platforms_pkey PRIMARY KEY (id);

-- FOREIGN KEY CONSTRAINTS

ALTER TABLE ONLY gaming.games_comments
    ADD CONSTRAINT games_comments_game_id_fkey FOREIGN KEY (game_id) REFERENCES gaming.games(id);


ALTER TABLE ONLY gaming.games_statuses
    ADD CONSTRAINT games_statuses_game_id_fkey FOREIGN KEY (game_id) REFERENCES gaming.games(id);


ALTER TABLE ONLY gaming.games_genres
    ADD CONSTRAINT games_genres_game_id_fkey FOREIGN KEY (game_id) REFERENCES gaming.games(id);


ALTER TABLE ONLY gaming.games_genres
    ADD CONSTRAINT games_genres_genre_id_fkey FOREIGN KEY (genre_id) REFERENCES gaming.genres(id);


ALTER TABLE ONLY gaming.games_platforms
    ADD CONSTRAINT games_platforms_game_id_fkey FOREIGN KEY (game_id) REFERENCES gaming.games(id);


ALTER TABLE ONLY gaming.games_platforms
    ADD CONSTRAINT games_platforms_platform_id_fkey FOREIGN KEY (platform_id) REFERENCES gaming.platforms(id);


ALTER TABLE ONLY gaming.list_items
    ADD CONSTRAINT list_items_game_id_fkey1 FOREIGN KEY (game_id) REFERENCES gaming.games(id);


ALTER TABLE ONLY gaming.list_items
    ADD CONSTRAINT list_items_list_id_fkey FOREIGN KEY (list_id) REFERENCES gaming.lists(id) ON UPDATE CASCADE ON DELETE CASCADE;


ALTER TABLE ONLY gaming.platforms
    ADD CONSTRAINT platforms_category_fkey FOREIGN KEY (category) REFERENCES gaming.platform_categories(id);


-- SEQUENCE VALUES

SELECT pg_catalog.setval('gaming.games_id_seq', 1, false);
SELECT pg_catalog.setval('gaming.genres_id_seq', 1, false);
SELECT pg_catalog.setval('gaming.platform_categories_id_seq', 1, false);
SELECT pg_catalog.setval('gaming.platforms_id_seq', 1, false);
